"""Aggregate completed runs and verify provenance, denominators, and witnesses."""
import pathlib,json,csv,hashlib,collections,datetime
ROOT=pathlib.Path('results/real-app/bundling-dataset');DATA=pathlib.Path('datasets/bundling-dataset')
read=lambda p:json.loads(p.read_text())
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
sel=read(DATA/'selection.json');old=read(ROOT/'prior-results-audit.json')
for name,h in read(DATA/'verification.json')['fileSha256'].items():assert sha(DATA/name)==h
provenance=read(pathlib.Path('scripts/real-app/robustness/legacy-patterns/provenance.json'))
for f in provenance['files']:assert sha(pathlib.Path('scripts/real-app/robustness/legacy-patterns/vendor')/f['name'])==f['sha256']
assert sha(pathlib.Path('scripts/real-app/robustness/legacy-patterns/recognizer.cjs'))==provenance['compiledRecognizerSha256']
base=pathlib.Path('scripts/real-app')
expected=(base/'robustness/legacy-patterns/adapted-module-graph.mjs').read_text().replace("from './recognize.mjs'","from '../robustness/legacy-patterns/recognize.mjs'").replace("from 'meriyah'","from './parse.mjs'").replace('slots={};','slots=Object.create(null);')
assert expected==(base/'bundling-dataset/module-graph.mjs').read_text()
assert (base/'bundling-dataset/inventory/analysis.mjs').read_bytes()==pathlib.Path('scripts/jquery/analysis.mjs').read_bytes()
rows=[];repos=[];checks=[];details=[]
for subj in sel['subjects']:
 p=ROOT/subj['slug']
 if any(x['repo']==subj['repo'] for x in old['skipped']):continue
 summary=read(p/'summary.json');prep=read(p/'prepared.json');tr=read(p/'target-traces.json');gt=read(p/'ground-truth.json');d=read(p/'detector-input.json');
 if 'sourceShards' in d:d.update(sources=[{k:v for k,v in read(p/x).items() if k in ('file','parser','sourceFile','sha256')} for x in d['sourceShards']],bundles=[{k:v for k,v in read(p/x).items() if k in ('file','parser','sourceFile','sha256')} for x in d['bundleShards']])
 arts=read(p/'artifacts.json');mods=read(p/'module-analysis-per-chunk.json')
 assert summary['repo']==subj['repo'] and summary['commit']==subj['commit'] and summary['modelCalls']==0
 assert len(summary['libraries'])<=10
 assert summary['sourceModuleAnalysis']['status']=='complete' and summary['bundleModuleAnalysis']['status']=='complete'
 for src in d['sources']:assert sha(p/src['sourceFile'])==src['sha256']
 for bundle in d['bundles']:assert sha(p/bundle['file'])==bundle['sha256']
 assert sha(p/'detector-input.json')==summary['provenance']['detectorInputSha256'] and sha(p/'ground-truth.json')==summary['provenance']['oracleSha256']
 for f in arts['files']:
  assert sha(pathlib.Path(f['js']))==f['jsSha256'] and sha(pathlib.Path(f['map']))==f['mapSha256']
 for item in old['prior']:assert sha(pathlib.Path(item['file']))==item['sha256']
 # Every promotion must have an earlier-round true pair as its two-graph witness.
 by={(t['variant'],t['build'],t['bundleId']):t for t in tr}
 for t in tr:
  if t['recovered'] and t['round']>0:
   w=t['parentWitness'];assert w
   parent=by[(t['variant'],t['build'],w['bundleId'])]
   assert parent['recovered'] and parent['round']<t['round'] and parent['sourceId']==w['sourceId']
 for c in summary['chunks']:assert c['verification']=='Fixed point equals independent BFS on oracle-pair intersection graph.'
 counts=summary['aggregate'];o=counts['original'];a=counts['original-patterns-intermodule']
 assert o['targets']==a['targets']==sum(bool(r['sourceId']) for r in gt['records'])
 for name,v in counts.items():
  xs=[t for t in tr if t['variant']==name];assert len(xs)==v['targets'] and sum(t['recovered'] for t in xs)==v['recovered']
  assert v['recovered']==sum(l['variants'][name]['recovered'] for l in summary['libraries'])
 assert a['recovered']>=o['recovered']
 base={'bundler':subj['bundler'],'repo':summary['repo'],'commit':summary['commit'],'selectedLibraries':len(summary['libraries']),'supportedTargets':o['targets'],'baselineRecovered':o['recovered'],'baselineRate':o['rate'],'intermoduleRecovered':a['recovered'],'intermoduleRate':a['rate'],'sourceFiles':prep['sourceFiles'],'sourceParseFailures':len(prep['parseFailures']),'analyzedChunks':len(d['bundles']),'collectedMapPairs':len(arts['files']),'bundleModules':summary['bundleModuleAnalysis']['modules'],'bundleResolvedCalls':summary['bundleModuleAnalysis']['resolvedCallSites'],'sourceAnalysisStatus':summary['sourceModuleAnalysis']['status'],'modelCalls':0}
 repos.append(base)
 origins=collections.Counter(r['origin'] for r in gt['records'] if r['status']=='unresolved')
 details.append({'repo':subj['repo'],'seedCounts':summary['seedCounts'],'sourceModuleAnalysis':summary['sourceModuleAnalysis'],'bundleModuleAnalysis':summary['bundleModuleAnalysis'],'allAnalyzedBundleFunctions':len(gt['records']),'oracleStatuses':dict(collections.Counter(r['status'] for r in gt['records'])),'unresolvedOrigins':dict(origins),'parserFallbackFiles':[{'file':s['file'],'side':'source','parser':s.get('parser')} for s in d['sources'] if s.get('parser','').startswith('acorn')]+[{'file':s['file'],'side':'bundle','parser':s.get('parser')} for s in d['bundles'] if s.get('parser','').startswith('acorn')],'artifactCoverage':arts.get('coverage'),'parseFailures':prep['parseFailures']})
 for l in summary['libraries']:
  v=l['variants'];n=l['supportedTargets'];rows.append({'bundler':subj['bundler'],'repo':subj['repo'],'commit':subj['commit'],'library':l['library'],'sourceFiles':l['sourceFiles'],'sourceParseFailures':l['sourceParseFailures'],'referenceFunctions':l['referenceFunctions'],'supportedTargets':n,'baselineRecovered':v['original']['recovered'],'baselineRate':v['original']['rate'],'intermoduleRecovered':v['original-patterns-intermodule']['recovered'],'intermoduleRate':v['original-patterns-intermodule']['rate'],'initialAnchors':v['original']['initialAnchors'],'unreached':v['original-patterns-intermodule']['unreached'],'coverageStatus':'no-supported-targets' if not n else 'partial-source-parsing' if l['sourceParseFailures'] else 'parsed-source-oracle-supported'})
 checks.append({'repo':subj['repo'],'artifactHashesMatch':True,'sourceAndBundleSnapshotsMatch':True,'moduleAnalysesCompleted':True,'inputHashesMatch':True,'denominatorsReconciled':True,'promotionWitnessesValid':True,'fixedPointBfsChecks':len(summary['chunks']),'priorSummariesUnchanged':True})
for name,data in [('repos.csv',repos),('per-library.csv',rows)]:
 with (ROOT/name).open('w') as f:
  w=csv.DictWriter(f,fieldnames=list(data[0]));w.writeheader();w.writerows(data)
def pct(x):return 'N/A' if x is None else f'{x*100:.2f}%'
def frac(r,prefix):return f"{r[prefix+'Recovered']:,}/{r['supportedTargets']:,} ({pct(r[prefix+'Rate'])})"
total=sum(r['supportedTargets'] for r in repos);b=sum(r['baselineRecovered'] for r in repos);a=sum(r['intermoduleRecovered'] for r in repos)
report=['# Bundling dataset: oracle connectivity simulation','',f"Completed {len(repos)} new targets across five bundlers; {len(old['skipped'])} previously tested targets skipped. {len(rows)} selected repo/library cases, {sum(r['supportedTargets']>0 for r in rows)} with at least one supported target. Model calls: **0**.",'',f"Supported-case aggregate: baseline **{b:,}/{total:,} ({pct(b/total)})**; original-pattern inter-module graph **{a:,}/{total:,} ({pct(a/total)})**. This is a target-weighted summary of selected libraries, not a population-wide or all-source-function recovery rate.",'','## Per repository','','| Bundler | Repository | Libraries | Baseline recovered / supported | With inter-module calls | Source parse failures / files |','|---|---|---:|---:|---:|---:|']
for r in repos:report.append(f"| {r['bundler']} | {r['repo']} | {r['selectedLibraries']} | {frac(r,'baseline')} | {frac(r,'intermodule')} | {r['sourceParseFailures']}/{r['sourceFiles']} |")
report += ['','## Protocol and interpretation','','- Reuse the prior protocol: at most ten loaded nonframework libraries per repository, selected by deduplicated embedded JS-family source bytes before oracle outcomes; include transitive dependencies and emitted lazy chunks. Library copies across chunks remain separate target cases. Browser-output presence is not navigation coverage.', '- Separate source and bundle graphs; radius-one undirected local call/argument/containment edges plus sibling window two. Seed proposals require a unique POG hash on both sides and at least ten property operations. Only oracle-confirmed seed proposals enter this connectivity experiment; wrong and unassessed proposals are logged.', '- At each synchronous round, directly select the ground-truth source function if it exists anywhere in the candidate neighborhood of accepted pairs, within the unchanged 18,000-character eligibility bound and one-to-one identity rule. No ranking, top-k pruning, validation, model endpoint, embeddings, or model cache. Stop at the fixed point and independently verify reachable pairs by BFS.', '- Ground truth uses unchanged innermost own-body source-map voting: at least two points, at least 80% purity, and a strict unique winner. Supported targets form the denominator. Unresolved labels, eliminated/inlined functions without a separate generated counterpart, and source files the inventory cannot parse do not enter that denominator. Non-one-to-one supported cases remain in it and are unrecovered.', '- No module-initialization matching, module-membership expansion, or oracle-derived graph edges. Initialization functions are not specially identified or removed from the existing denominator.', '- The augmented variant reuses the authors original D-Bundlr webpack recognition patterns and matcher with the previous bounded static binding solver. It is not the authors full end-to-end tool. No new recognizers were written for these bundlers.','', '## Coverage and implementation observations','', '- ZyPlayer is strongly affected by tdesign-icons-vue-next: only 8/41,489 supported cases recover (0.0193%). It has four confirmed initial anchors; 41,480 unrecovered cases have no accepted bundle neighbor at the fixed point, and one has no true source candidate in its neighborhood. Monaco recovers 40,088/44,502 (90.08%). These per-library differences are obscured by the repository aggregate.', f"- The original-pattern recognizer found {sum(r['bundleModules'] for r in repos)} bundled modules and {sum(r['bundleResolvedCalls'] for r in repos)} resolved bundled inter-module call sites. Zero recognized modules means the current recognizer supplies no additional bundle edges; it does not mean a bundle contains no modules.", '- Turbopack sources include TypeScript/TSX that the current inventory cannot parse. Their displayed rates concern only source-map-supported, parsed function cases. Per-library rows with zero supported targets are **N/A**, never 0% or 100%. See `coverage.json` and the CSV source-parse-failure columns before comparing bundlers.', '- Framework exclusion is extended to Next.js for the new Next targets; its own runtime does not count as a library. Preliminary within-run results before this scope correction are archived under each Turbopack subject and are not reported as final. The justjavac map label shared is also excluded: the map attributes five files to node_modules/shared, but the build container has no installed shared package; its ownership is unresolved and it supplies no supported targets.', '- Collected existing Turbopack outputs from the map-enabled containers. Pair JavaScript with the explicit sourceMappingURL because Next can use a different map basename; justjavac increased from one adjacent filename pair to fourteen valid pairs. Any unmapped output is listed in each artifacts.json. No application rebuild or switch to webpack was used for those targets.', '- ZyPlayer uses the browser renderer output, including browser worker chunks; main/preload builds are excluded. Cypress and ZyPlayer reuse existing local source-mapped outputs. Artifact hashes are pinned here; the external dataset remains unchanged.', '- Focalboard tests only `experiments/webext`, not its webpack main application. Built Parcel 2.6.2 in an isolated workspace copy. Aligned @parcel/transformer-sass 2.0.0 to 2.6.2 (within the original ^2.0.0 range), enabled production maps, and decoded the emitted inline data-URL maps without changing generated code. Extension ZIP packaging and authenticated navigation are unnecessary for this static experiment.', '- Large ZyPlayer inventories are serialized into per-source/per-chunk JSON shards to avoid V8 string-size limits; this changes storage only.', '- Two narrow implementation repairs are isolated to the new experiment scripts: an Object.create(null) export dictionary avoids inherited constructor-name collisions, and Acorn 8.19.0 is a fallback for valid JavaScript rejected by Meriyah 6.0.6. Meriyah remains the first parser; code text and offsets are preserved, with no TS/JSX transpilation. Frozen prior scripts/results are unchanged. `parser-compatibility.json` checks that previously failed sources do not silently gain support and that the standard-JS inventory remains equal.', '', '## Per library','','| Bundler | Repository | Library | Supported | Recovered | Rate | Source parse failures / files |','|---|---|---|---:|---:|---:|---:|']
for r in rows:report.append(f"| {r['bundler']} | {r['repo']} | {r['library']} | {r['supportedTargets']} | {r['intermoduleRecovered']} | {pct(r['intermoduleRate'])} | {r['sourceParseFailures']}/{r['sourceFiles']} |")
report += ['','## Reproduction and files','','From the FAPI Study workspace, for an uncompleted subject with a populated artifact manifest:','','```sh','node --max-old-space-size=16384 scripts/real-app/bundling-dataset/prepare.mjs <slug>','node --max-old-space-size=16384 scripts/real-app/bundling-dataset/run.mjs <slug>','python3 scripts/real-app/bundling-dataset/report.py','```','','CSV rate fields use fractions in [0,1]; this report displays percentages. `repos.csv` contains repository aggregates; `per-library.csv` contains every selected library, including N/A cases; `coverage.json` contains oracle and parser limits; `verification.json` records checks. Each subject retains artifact hashes, exact detector/oracle inputs, source snapshots, seed audit, per-target round/witness traces, module analysis and logs. Existing prepared inputs are reused; remove outputs only for an intentional new version of an experiment.']
(ROOT/'REPORT.md').write_text('\n'.join(report)+'\n')
(ROOT/'coverage.json').write_text(json.dumps(details,indent=2)+'\n')
(ROOT/'summary.json').write_text(json.dumps({'createdAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'datasetSelectionSha256':sha(DATA/'selection.json'),'newTargets':len(repos),'previouslyTestedSkipped':old['skipped'],'modelCalls':0,'selectedRepoLibraryCases':len(rows),'casesWithSupportedTargets':sum(r['supportedTargets']>0 for r in rows),'aggregate':{'supportedTargets':total,'baselineRecovered':b,'baselineRate':b/total,'intermoduleRecovered':a,'intermoduleRate':a/total},'repos':repos},indent=2)+'\n')
(ROOT/'verification.json').write_text(json.dumps({'checks':checks,'noModelExecution':True,'originalPatternFilesUnmodified':True,'datasetMetadataUnchanged':True,'note':'Existing simulation independently checks fixed point against pair-intersection BFS; report also checks round witnesses, target counts and pinned input/artifact hashes.'},indent=2)+'\n')
print(json.dumps({'repos':len(repos),'libraries':len(rows),'supported':total,'recovered':a,'rate':a/total},indent=2))
